  public static String serializeRecommendedParams(final String transaction, final Encoding transactionEncoding) {
    return String.format("""
            "transaction":"%s",
            "options":{
              "transactionEncoding":"%s",
              "recommended":true
            }""",
        transaction,
        transactionEncoding
    );
  }
